import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as s,o,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Gemini Family Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/gemini/gemini-glossary.md","filePath":"products/ai-coding/gemini/gemini-glossary.md","lastUpdated":1787110548000}'),a={name:"products/ai-coding/gemini/gemini-glossary.md"};function r(i,e,l,c,d,p){return o(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="gemini-family-glossary" tabindex="-1">Gemini Family Glossary <a class="header-anchor" href="#gemini-family-glossary" aria-label="Permalink to &quot;Gemini Family Glossary&quot;">​</a></h1><blockquote><p>This document explains the <strong>concepts</strong> in the Gemini family: what each one is, why it exists, what role it plays in the ecosystem, and how it differs from the concept next to it.</p><p>For commands, config keys and subscription numbers see the <a href="./gemini-cheatsheet.html">cheatsheet</a>; for copy-paste recipes see the <a href="./gemini-cookbook.html">cookbook</a>.</p></blockquote><h2 id="how-the-concepts-relate" tabindex="-1">How the concepts relate <a class="header-anchor" href="#how-the-concepts-relate" aria-label="Permalink to &quot;How the concepts relate&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                        ┌─────────────────────────────┐</span></span>
<span class="line"><span>                        │    The agent-first premise   │</span></span>
<span class="line"><span>                        │  AI acts; it does not just   │</span></span>
<span class="line"><span>                        │        complete code         │</span></span>
<span class="line"><span>                        └──────────────┬──────────────┘</span></span>
<span class="line"><span>                                       │ realised as</span></span>
<span class="line"><span>        ┌──────────────────────────────┼──────────────────────────────┐</span></span>
<span class="line"><span>        │                              │                              │</span></span>
<span class="line"><span> ┌──────▼──────┐               ┌───────▼───────┐              ┌───────▼───────┐</span></span>
<span class="line"><span> │  Gemini CLI │               │  Antigravity  │              │     Jules     │</span></span>
<span class="line"><span> │ local shell │               │ local, multi- │              │   cloud VM    │</span></span>
<span class="line"><span> │             │               │   surface     │              │               │</span></span>
<span class="line"><span> └──────┬──────┘               └───────┬───────┘              └───────┬───────┘</span></span>
<span class="line"><span>        │                              │                              │</span></span>
<span class="line"><span> constraints + memory        constraints + capability        constraints + output</span></span>
<span class="line"><span>        │                              │                              │</span></span>
<span class="line"><span> ┌──────▼──────────┐    ┌──────────────▼──────────────┐    ┌──────────▼────────┐</span></span>
<span class="line"><span> │ GEMINI.md       │    │ Rules (global + workspace)   │    │ AGENTS.md         │</span></span>
<span class="line"><span> │ system.md       │    │ Skills (dir + SKILL.md)      │    │ Pull request      │</span></span>
<span class="line"><span> │ Extensions      │    │ Workflows (/name)            │    └───────────────────┘</span></span>
<span class="line"><span> └──────┬──────────┘    │ Subagents (concurrent)       │</span></span>
<span class="line"><span>        │               │ Artifacts (reviewable)       │</span></span>
<span class="line"><span>        │               └──────────────┬──────────────┘</span></span>
<span class="line"><span>        │                              │</span></span>
<span class="line"><span>        └───────────┬──────────────────┘</span></span>
<span class="line"><span>                    │ all reach out through</span></span>
<span class="line"><span>            ┌───────▼────────┐</span></span>
<span class="line"><span>            │      MCP       │  external tools (GitHub / browser / database)</span></span>
<span class="line"><span>            └────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Cross-cutting safety and recovery:</span></span>
<span class="line"><span>  Trusted Folder (project config loads only when trusted) · Checkpoint (snapshot before edits)</span></span>
<span class="line"><span>  Session (list and resume a whole conversation) · Headless Mode (one-shot, pipeline-friendly)</span></span></code></pre></div><p>One-line reading: <strong>the paradigm (agent-first) decides the product shapes (CLI / Antigravity / Jules), the product shape decides which file you use to constrain it (GEMINI.md / Rules / AGENTS.md), and MCP decides how much of the world it can touch.</strong></p><h2 id="agent-first" tabindex="-1">Agent-first <a class="header-anchor" href="#agent-first" aria-label="Permalink to &quot;Agent-first&quot;">​</a></h2><p><strong>What it is</strong>: a product design premise — assume the AI is an actor that can plan on its own, call tools and execute multi-step work, rather than an engine that waits for you to type half a line and finishes the rest.</p><p><strong>Why the concept matters</strong>: it explains why Antigravity is not &quot;another editor with AI bolted on&quot;. A completion tool&#39;s unit of interaction is one keystroke; an agent-first tool&#39;s unit is one task. That changes what you have to feed it: completion needs a cursor position, an agent needs a goal, constraints and acceptance criteria.</p><p><strong>Ecosystem role</strong>: this is the shared premise of the whole Gemini coding family. Gemini CLI expresses it in the terminal, Antigravity on the desktop, Jules in the cloud.</p><p><strong>Versus &quot;AI completion&quot;</strong>: completion lives inside your edit loop; an agent owns an edit loop of its own. When completion goes wrong you see it immediately; when an agent goes wrong it may only surface twenty files later — which is exactly why <a href="#checkpoint">Checkpoint</a> and <a href="#artifact">Artifact</a> exist.</p><p><strong>Official docs</strong>: <a href="https://antigravity.google/docs/home" target="_blank" rel="noreferrer">Antigravity docs home</a></p><h2 id="surface" tabindex="-1">Surface <a class="header-anchor" href="#surface" aria-label="Permalink to &quot;Surface&quot;">​</a></h2><p><strong>What it is</strong>: Antigravity&#39;s multiple entry points. The official docs describe the desktop app, the CLI (terminal UI), the SDK (Python) and IDE integration as different surfaces built on <strong>the same agent harness</strong>.</p><p><strong>Why the concept matters</strong>: it answers a very common confusion — &quot;do the rules I configured on the desktop still apply in the CLI?&quot; Because they share one harness, constraints like rules and skills are cross-surface. You pick the entry point that fits how you are working right now, without learning a second mental model.</p><p><strong>How it works</strong>: the surface owns the interaction shape (GUI / terminal / programmatic API); the harness owns the agent&#39;s planning, tool calling and execution.</p><p><strong>Versus &quot;multiple clients&quot;</strong>: multiple clients are usually different shells over one backend API, and their capabilities are often unequal. Surfaces share the agent runtime itself.</p><p><strong>When to use which</strong>: desktop for interactive exploration, CLI to slot into existing scripts, SDK to embed the agent in your own automation.</p><p><strong>Official docs</strong>: <a href="https://antigravity.google/docs/home" target="_blank" rel="noreferrer">Antigravity docs home</a></p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p><strong>What it is</strong>: long-lived behavioural constraint files. Antigravity has two levels — global rules in <code>~/.gemini/GEMINI.md</code>, workspace rules in the <code>.agents/rules</code> directory. The docs state a hard limit of 12,000 characters per rule file.</p><p><strong>Why it matters</strong>: making an agent re-derive your preferences from scratch on every task is expensive and unstable. Rules pin down invariants like &quot;we use pnpm, never npm&quot; or &quot;every component must be typed&quot; so you never restate them.</p><p><strong>How it works</strong>: four activation modes are documented — Manual (referenced by hand), Always On (always loaded), Model Decision (the model judges whether it is needed), and Glob (triggered by file patterns). Rules can cross-reference each other with <code>@filename</code>.</p><p><strong>Versus <a href="#skill">Skill</a></strong>: a rule says &quot;you must always do this&quot; (a constraint); a skill says &quot;when you hit this kind of work, follow this procedure&quot; (a capability). Constraints are always present; capabilities load on demand.</p><p><strong>Versus Gemini CLI&#39;s <code>GEMINI.md</code></strong>: the purpose is the same (supply long-lived context) but the location and layering differ — do not mix the two sets of paths.</p><p><strong>When to use</strong>: coding conventions, stack constraints, prohibitions, review checklists.</p><p><strong>Official docs</strong>: <a href="https://antigravity.google/docs/rules-workflows" target="_blank" rel="noreferrer">Rules &amp; Workflows</a></p><h2 id="skill" tabindex="-1">Skill <a class="header-anchor" href="#skill" aria-label="Permalink to &quot;Skill&quot;">​</a></h2><p><strong>What it is</strong>: a <strong>directory</strong> containing a <code>SKILL.md</code>. It lives at <code>.agents/skills/&lt;folder&gt;/SKILL.md</code> (travels with the repo) or <code>~/.gemini/config/skills/&lt;folder&gt;/SKILL.md</code> (global). In the frontmatter, <code>description</code> is required and <code>name</code> is optional.</p><p><strong>Why it matters</strong>: it turns a specialised procedure (&quot;how we cut a release here&quot;, &quot;how we write these E2E tests&quot;) from a one-off prompt into a reusable asset you can commit and share with the team.</p><p><strong>How it works</strong>: <code>description</code> is what the model uses to judge whether the skill is relevant right now, so write it like a trigger condition, not like a title. Because a skill is a directory, you can ship scripts, templates and sample data alongside it and have <code>SKILL.md</code> reference them.</p><p><strong>Common misconception</strong>: a skill is <strong>not</strong> a flat <code>.md</code> file. The <code>.agents/skills/xxx.md</code> form seen in older docs is wrong. <code>.agent/skills</code> (singular) is kept only for backward compatibility; use <code>.agents/skills</code> for anything new.</p><p><strong>When to use</strong>: release procedures, migration playbooks, domain-specific debugging steps.</p><p><strong>Official docs</strong>: <a href="https://antigravity.google/docs/skills" target="_blank" rel="noreferrer">Skills</a></p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><p><strong>What it is</strong>: a multi-step procedure you invoke explicitly as <code>/&lt;workflow-name&gt;</code>.</p><p><strong>Why it matters</strong>: some procedures should start <strong>when a human says so</strong>, not when the model decides. Skills are matched passively through their description; workflows are triggered actively through a slash command.</p><p><strong>Versus <a href="#skill">Skill</a></strong>: who holds the trigger. The model decides whether to use a skill; you decide when to run a workflow.</p><p><strong>When to use</strong>: pre-release checks, weekly report generation, a fixed-format code review.</p><p><strong>Official docs</strong>: <a href="https://antigravity.google/docs/rules-workflows" target="_blank" rel="noreferrer">Rules &amp; Workflows</a></p><h2 id="subagent" tabindex="-1">Subagent <a class="header-anchor" href="#subagent" aria-label="Permalink to &quot;Subagent&quot;">​</a></h2><p><strong>What it is</strong>: a subordinate agent the main agent dispatches to do work. The official Antigravity docs call these Asynchronous Subagents.</p><p><strong>Why it matters</strong>: a single agent&#39;s context window is a finite resource. Sending subagents to read one module each and return conclusions — so the main agent consumes conclusions rather than raw files — lets the same window cover a much larger task.</p><p><strong>How it works</strong>: subagents run independently and return asynchronously, so the main agent can keep pushing other branches forward while it waits.</p><p><strong>The cost</strong>: concurrency means changes arrive from several directions at once, raising the risk of conflicts and of two subagents editing the same file. That is precisely why <a href="#artifact">Artifact</a> is valuable — you need to be able to review what each one intends to do.</p><p><strong>Official docs</strong>: <a href="https://antigravity.google/docs/home" target="_blank" rel="noreferrer">Antigravity docs home</a></p><h2 id="artifact" tabindex="-1">Artifact <a class="header-anchor" href="#artifact" aria-label="Permalink to &quot;Artifact&quot;">​</a></h2><p><strong>What it is</strong>: a reviewable intermediate product the agent emits while working — a plan, a task list, a verification record.</p><p><strong>Why it matters</strong>: the more autonomous the agent, the less obvious &quot;what is it actually about to do&quot; becomes. Artifacts convert that black-box middle state into something you can read and veto. They are the brake that comes with the autonomy, not decoration.</p><p><strong>Ecosystem role</strong>: this is the same design motive as Jules producing a plan for human approval before it starts — <strong>give a human a veto point before anything is touched</strong>.</p><p><strong>When to use</strong>: read the plan before a cross-module refactor; use the verification record afterwards to decide how much to trust the result.</p><p><strong>Official docs</strong>: <a href="https://antigravity.google/docs/home" target="_blank" rel="noreferrer">Antigravity docs home</a></p><h2 id="checkpoint" tabindex="-1">Checkpoint <a class="header-anchor" href="#checkpoint" aria-label="Permalink to &quot;Checkpoint&quot;">​</a></h2><p><strong>What it is</strong>: Gemini CLI snapshots automatically before every file modification, and <code>/restore</code> rolls back. It is <strong>off</strong> by default; set <code>general.checkpointing.enabled</code> to <code>true</code>.</p><p><strong>Why it matters</strong>: one agent task can change a dozen files in a row. By the time you realise the direction was wrong, <code>git checkout</code> would also throw away the edits you made by hand. A checkpoint gives you the finer granularity of &quot;back to the moment before the agent touched anything&quot;.</p><p><strong>Versus Git</strong>: Git records the history you <strong>want to keep</strong>; checkpoints record automated changes you <strong>might want to undo</strong>. They complement each other — checkpoints do not replace commits.</p><p><strong>When to use</strong>: turn it on before letting an agent do a broad refactor.</p><p><strong>Official docs</strong>: <a href="https://geminicli.com/docs/" target="_blank" rel="noreferrer">Gemini CLI docs</a></p><h2 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h2><p><strong>What it is</strong>: the complete record of one conversation, which can be listed and resumed.</p><p><strong>Why it matters</strong>: real work gets interrupted. Sessions mean &quot;yesterday&#39;s context&quot; does not depend on you pasting it all back in.</p><p><strong>How it works</strong>: sessions are kept indefinitely by default, and can be cleaned up by configuration — <code>general.sessionRetention.enabled</code> turns cleanup on, <code>maxAge</code> (e.g. <code>&quot;30d&quot;</code>) bounds it by time, <code>maxCount</code> by number, and <code>minRetention</code> (default <code>&quot;1d&quot;</code>) sets the floor.</p><p><strong>Versus <a href="#checkpoint">Checkpoint</a></strong>: a session saves the <strong>conversation</strong>, a checkpoint saves the <strong>files</strong>. Resuming a session does not revert code.</p><p><strong>Official docs</strong>: <a href="https://geminicli.com/docs/" target="_blank" rel="noreferrer">Gemini CLI docs</a></p><h2 id="headless-mode" tabindex="-1">Headless Mode <a class="header-anchor" href="#headless-mode" aria-label="Permalink to &quot;Headless Mode&quot;">​</a></h2><p><strong>What it is</strong>: one-shot execution with the <code>-p</code> (prompt) flag, returning the result directly instead of entering the interactive UI. Pair it with <code>--output-format json</code> for structured output.</p><p><strong>Why it matters</strong>: this is the interface that lets AI enter an existing engineering pipeline. An interactive UI is friendly to humans and hostile to scripts; headless mode makes <code>gemini</code> an ordinary Unix command that pipes, CI jobs and Git hooks can call.</p><p><strong>How it works</strong>: stdin in, stdout out — which is what makes <code>npm run build 2&gt;&amp;1 | gemini -p &quot;analyse this error&quot;</code> work.</p><p><strong>When to use</strong>: build-failure analysis, batch generation, CI checks.</p><p><strong>Official docs</strong>: <a href="https://geminicli.com/docs/" target="_blank" rel="noreferrer">Gemini CLI docs</a></p><h2 id="trusted-folder" tabindex="-1">Trusted Folder <a class="header-anchor" href="#trusted-folder" aria-label="Permalink to &quot;Trusted Folder&quot;">​</a></h2><p><strong>What it is</strong>: a security boundary. With <code>security.folderTrust.enabled</code> turned on, only trusted directories load project-level configuration; the trust list lives in <code>~/.gemini/trustedFolders.json</code>.</p><p><strong>Why it matters</strong>: <code>.gemini/settings.json</code> and custom commands travel with the repository. If you clone an unfamiliar repo and start an agent inside it, the repo&#39;s own configuration gets a chance to influence agent behaviour. Trust makes &quot;I have read and accepted this repo&#39;s configuration&quot; an explicit act.</p><p><strong>How it works</strong>: in an untrusted directory, project settings and custom commands do not take effect.</p><p><strong>Versus a sandbox</strong>: trust controls <strong>whose configuration is loaded</strong>; a sandbox controls <strong>what execution can reach</strong>. Different problems.</p><p><strong>Official docs</strong>: <a href="https://geminicli.com/docs/" target="_blank" rel="noreferrer">Gemini CLI docs</a></p><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p><strong>What it is</strong>: the Model Context Protocol, an open protocol for connecting agents to external tools and data sources.</p><p><strong>Why it matters</strong>: without MCP an agent can only read and write local files and run local commands. With it, the agent can query GitHub issues, drive a browser, read a database — the capability boundary widens from &quot;this machine&quot; to &quot;these services&quot;.</p><p><strong>Ecosystem role</strong>: it is the common plug between the Gemini family and the outside world, supported by Gemini CLI, Antigravity and Code Assist alike.</p><p><strong>How it works</strong>: an MCP server exposes a set of tools and the agent calls them when needed. In Gemini CLI, MCP servers are usually installed through an <a href="#extension">Extension</a>.</p><p><strong>Security note</strong>: MCP servers often need credentials (a GitHub token, say). Put credentials in environment variables or <code>.gemini/.env</code>. <strong>Do not put them in configuration files that get committed, and do not type them on the command line</strong> — the command line lands in shell history.</p><p><strong>Official docs</strong>: <a href="https://geminicli.com/docs/" target="_blank" rel="noreferrer">Gemini CLI docs</a></p><h2 id="extension" tabindex="-1">Extension <a class="header-anchor" href="#extension" aria-label="Permalink to &quot;Extension&quot;">​</a></h2><p><strong>What it is</strong>: Gemini CLI&#39;s unit of installation; the most common use is installing an MCP server. Install with <code>gemini extensions install &lt;git-url&gt;</code>.</p><p><strong>Why it matters</strong>: it turns &quot;configure an MCP server&quot; from hand-written JSON into one command.</p><p><strong>How it works</strong>: installs from a Git repository URL. The URL must include the organisation name — the official GitHub MCP server is <code>https://github.com/github/github-mcp-server</code>. Older docs contained <code>https://github.com/github-mcp-server</code> (organisation missing), which cannot install.</p><p><strong>When to use</strong>: wiring up GitHub, browser automation, internal services. See the <a href="https://geminicli.com/extensions/" target="_blank" rel="noreferrer">official extension gallery</a>.</p><p><strong>Official docs</strong>: <a href="https://geminicli.com/extensions/" target="_blank" rel="noreferrer">Gemini CLI extensions</a></p><h2 id="agents-md" tabindex="-1">AGENTS.md <a class="header-anchor" href="#agents-md" aria-label="Permalink to &quot;AGENTS.md&quot;">​</a></h2><p><strong>What it is</strong>: an instruction file in the <strong>repository root</strong> that Jules reads automatically.</p><p><strong>Why it matters</strong>: Jules works alone in a cloud VM with you nowhere nearby. It needs to know in advance how this repo installs dependencies, how it runs tests and what is off limits — otherwise it can only guess.</p><p><strong>Versus <a href="#rules">Rules</a> and <code>GEMINI.md</code></strong>: all three are long-lived instructions for an agent, but they belong to different products and live in different places. Jules reads <code>AGENTS.md</code> at the repo root; Antigravity reads <code>~/.gemini/GEMINI.md</code> and <code>.agents/rules</code>; Gemini CLI reads <code>GEMINI.md</code> and <code>.gemini/system.md</code>. <strong>Do not assume one file serves the whole family.</strong></p><p><strong>When to use</strong>: spell out the install command, the test command, the code style and the directories nothing may touch.</p><p><strong>Official docs</strong>: <a href="https://jules.google/docs/" target="_blank" rel="noreferrer">Jules docs</a></p><h2 id="google-flow" tabindex="-1">Google Flow <a class="header-anchor" href="#google-flow" aria-label="Permalink to &quot;Google Flow&quot;">​</a></h2><p><strong>What it is</strong>: Google&#39;s AI creative studio. It generates and refines video and images from text / frames / ingredients using Veo 3.1, Nano Banana and Gemini Omni. Entry point: <a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">labs.google/fx/tools/flow</a>.</p><p><strong>Why it matters</strong>: the coding line (CLI / Antigravity / Jules) delivers code in a repository. Presenting a feature still needs a finished clip — a landing-page film, a product demo, a storyboard. Flow fills that gap; it is not another coding entry point.</p><p><strong>Ecosystem role</strong>: the counterpart of Claude Design. Design hands off an interface prototype; Flow hands off a piece of film. The same subscription tier sets Flow credits and Antigravity / Jules quota, but the ledgers are separate.</p><p><strong>Versus <a href="./canvas.html">Canvas</a></strong>: Canvas gives you a clickable workspace beside a Gemini conversation; the output is an interactive prototype. Flow outputs video / images. Use Canvas for DOM, Flow for a finished clip.</p><p><strong>Versus Flow Music</strong>: Flow Music lives at <a href="https://www.flowmusic.app/" target="_blank" rel="noreferrer">flowmusic.app</a> and makes songs and music videos. Pro maps to its own Plus plan (10,000 music credits / month). <strong>The two credit ledgers do not mix.</strong></p><p><strong>Flow Sessions</strong>: an artist collaboration programme on the landing page, not a daily product.</p><p><strong>Official docs</strong>: <a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">product entry</a>, <a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">credits</a>. Product page: <a href="./flow.html">Flow</a>.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./gemini-cheatsheet.html">Cheatsheet</a> — commands, config keys, subscription tiers</li><li><a href="./gemini-cookbook.html">Cookbook</a> — recipes by scenario</li><li><a href="./index.html">Learning map</a> — what to learn in what order</li></ul>`,104)])])}const y=t(a,[["render",r]]);export{f as __pageData,y as default};
